<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {useProjectStore} from '../stores/project';
import type {Instance,Release,AdminTaskListItem,AdminTaskView,StudioMemberMetadata} from '@loreviva/sdk-ts';
import FieldErrors from '../components/FieldErrors.vue';
import MemoryPanel from '../components/MemoryPanel.vue';
import {createCommandRunner} from '../lib/commands';
import {collectPages} from '../lib/pages';
const s=useProjectStore();const runner=createCommandRunner(s.client);const instances=ref<Instance[]>([]);const releases=ref<Release[]>([]);const tasks=ref<AdminTaskListItem[]>([]);const members=ref<StudioMemberMetadata[]>([]);const release=ref('');const participant=ref('');const error=ref<unknown>();const notice=ref('');const detail=ref<AdminTaskView>();const cursor=ref<string>();
let readVersion=0;
async function refresh(){const version=++readVersion;const active=s.client;try{const currentInstances=await collectPages(cursor=>active.call('listAdminInstances',{query:{product_id:s.productId,...(cursor?{cursor}:{})}}));const currentReleases=await collectPages(cursor=>active.call('listContentReleases',{query:{product_id:s.productId,...(cursor?{cursor}:{})}}));const page=await active.call('listAdminTasks',{query:{product_id:s.productId}});if(version!==readVersion||active!==s.client)return;instances.value=currentInstances;releases.value=currentReleases;tasks.value=page.items;cursor.value=page.next_cursor;window.dispatchEvent(new Event('studio-current-state'));error.value=undefined}catch(e){if(version===readVersion&&active===s.client)error.value=e}}
async function registeredParticipants(){const active=s.client;try{const currentMembers=await collectPages(cursor=>active.call('listAdminMembers',{query:{scope_type:'PRODUCT',tenant_id:s.tenantId,product_id:s.productId,limit:100,...(cursor?{cursor}:{})}}));if(active===s.client)members.value=currentMembers}catch(e){if(active===s.client)error.value=e}}
async function more(){try{if(!cursor.value)return;const page=await s.client.call('listAdminTasks',{query:{product_id:s.productId,cursor:cursor.value}});tasks.value.push(...page.items);cursor.value=page.next_cursor}catch(e){error.value=e;cursor.value=undefined}}
// Creation does not start an instance, and a control receipt confirms admission rather than the final runtime state. Retain the pending command's identity for recovery; WORLD tasks expose directory state here, not ADMIN detail.
async function create(){try{if(!release.value||!participant.value)throw Error('请选择发布版本与已登记参与者');const instance=await runner.run('createAdminInstance',{headers:{'Idempotency-Key':crypto.randomUUID()},body:{product_id:s.productId,release_id:release.value,initial_participants:[participant.value],mode:'PRIVATE',client_capabilities:['TEXT','STAGE_2D']}});instances.value.push(instance);notice.value='实例状态：'+instance.instance_state+'。尚未发起 START。'}catch(e){error.value=e}}
async function control(instance:Instance,command:'START'|'PAUSE'|'RESUME'|'END'){try{const originalCommand=runner.pending.value?.operation==='controlAdminInstance'?(runner.pending.value.input as {body:{command:string}}).body.command:command;const receipt=await runner.run('controlAdminInstance',{path:{instance_id:instance.scope.world_instance_id},headers:{'Idempotency-Key':crypto.randomUUID()},body:{product_id:s.productId,expected_versions:instance.versions,command}});notice.value=originalCommand+' 已受理：'+receipt.task_id+'，请刷新确认任务与实例状态。';await refresh()}catch(e){error.value=e}}
async function inspect(task:AdminTaskListItem){try{if(task.family!=='ADMIN'){notice.value='WORLD 任务仅显示当前目录的真实状态与三条费用轴；客户任务详情由 Task8 接通。';detail.value=undefined;return}detail.value=await s.client.call('getAdminTask',{path:{task_id:task.task_id},query:{product_id:s.productId}})}catch(e){error.value=e}}
onMounted(refresh);
</script>
<template><div class="page-heading"><div><p class="eyebrow">发布之后，单独启动</p><h1>运行中心</h1><p>实例状态、任务状态与费用状态分别显示。</p></div><button @click="refresh">刷新当前状态</button></div><FieldErrors :error="error"/><p v-if="notice" role="status">{{notice}}</p><section class="panel"><h2>创建实例</h2><div class="toolbar"><label>发布版本<select v-model="release"><option value="">请选择</option><option v-for="r in releases" :key="r.release_id" :value="r.release_id">{{r.input.name}} · {{r.release_id}}</option></select></label><button @click="registeredParticipants">读取登记参与者</button><label>参与者<select v-model="participant"><option value="">请选择</option><option v-for="m in members" :key="m.credential_id" :value="m.subject_id">{{m.subject_id}}</option></select></label><button class="primary" @click="create">创建 PRIVATE 实例</button></div><p class="muted">当前使用 TEXT / STAGE_2D，未宣称音频、动画或完整客户接入已实现。</p></section><section class="panel"><h2>实例</h2><table><thead><tr><th>实例</th><th>状态</th><th>独立操作</th></tr></thead><tbody><tr v-for="instance in instances" :key="instance.scope.world_instance_id"><td>{{instance.scope.world_instance_id}}</td><td>{{instance.instance_state}}</td><td class="actions"><button v-if="instance.instance_state==='CREATED'" @click="control(instance,'START')">START 启动</button><button v-if="instance.instance_state==='RUNNING'" @click="control(instance,'PAUSE')">暂停</button><button v-if="instance.instance_state==='PAUSED'" @click="control(instance,'RESUME')">恢复</button><button v-if="instance.instance_state!=='ENDED'" @click="control(instance,'END')">结束</button></td></tr></tbody></table><MemoryPanel v-for="instance in instances" :key="instance.scope.world_instance_id" :instance-id="instance.scope.world_instance_id"/></section><section class="panel"><h2>任务目录</h2><table><thead><tr><th>任务</th><th>执行状态</th><th>费用轴</th></tr></thead><tbody><tr v-for="task in tasks" :key="task.task_id"><td><button class="quiet" @click="inspect(task)">{{task.task_kind}} · {{task.task_id}}</button></td><td>{{task.task_state}}</td><td v-if="task.family==='WORLD'">供应商 {{task.accounting_status.supplier_reconciliation_state}}<br>服务 {{task.accounting_status.service_settlement_state}}<br>风险 {{task.accounting_status.platform_risk_state}}</td><td v-else>未提供金额；不推定已结算</td></tr></tbody></table><button v-if="cursor" @click="more">下一页</button><section v-if="detail"><h3>{{detail.task_kind}} · {{detail.task_state}}</h3><p>Mock：{{detail.mock_only}} · 结果资产 {{detail.result_asset_id??'尚无'}}</p><FieldErrors :findings="detail.findings"/></section></section><section class="panel future"><h2>后续接入</h2><p>Task8 客户 SDK / 参考客户端、Task10 完整分析财务、Task11 维护备份恢复尚未接通。当前目录不代表这些能力已验收。</p></section></template>
